const root = window.tree && window.tree.getTreeElementById ? window.tree.getTreeElementById('root') : null;
if (!root) {
	aras.AlertError(aras.getResource('../Modules/aras.innovator.QueryBuilder/', 'item.action.execute_in_tearoff.warning'));
	return;
}
window.tree.startExecuteAction(root);
